-- Custom SQL migration file, put your code below! --
-- #130: the messages an adoption application sends. The applicant hears
-- at every step; the listing organisation's representatives too, but no
-- message names the applicant or carries their contact (they sign in to
-- see it, from in_contact on); coordinators hear that one is waiting or
-- was withdrawn. A coordinator's reason for an ending is never sent. Data,
-- not seed, like #69's defaults: production is never seeded. Staff edit
-- the wording afterwards (new versions); FOA approves the copy (HR-61).
-- Email and in-app only: SMS waits for registered DLT templates (HR-14).
INSERT INTO "message_template" ("key", "channel", "subject", "body", "variables", "updated_at") VALUES
  ('adoption.application_received', 'email', 'We have your application to adopt {{animal.name}}',
